Namespace: MNELIB · Library: MNE Library #include <mne/mne_description_parser.h> class MNELIB::MNEDescriptionParser Parses MNE-C style averaging (.ave) and covariance (.cov) description files. File format is a keyword-value text format with nested blocks: average { ... category { ... } ... } cov { ... def { ... } ... } Lines starting with '#' are comments. src/examples/ex_mne_api/main.cpp // An MNE-C averaging description (mne_process_raw --ave), parsed and run on the raw recording const QString aveDesc = tmp.filePath("audvis.ave"); QFile descFile(aveDesc); ok &= descFile.open(QIODevice::WriteOnly | QIODevice::Text); descFile.write("average {
" " category {
" " name "Left Auditory"
" " event 1
" " tmin -0.1
" " tmax 0.3
" " bmin -0.1
" " bmax 0.0
" " }
" "}
"); descFile.close(); AverageDescription averaging; MNEDescriptionParser::parseAverageFile(aveDesc, averaging); QString log; const FiffEvokedSet averages = FiffEvokedSet::computeAverages(raw, averaging, events.events, log);
